@Component
public class RateLimitFilter extends OncePerRequestFilter {

    private static final int MAX_REQUESTS_PER_HOUR = 100;
    private static final Duration WINDOW = Duration.ofHours(1);
    private final StringRedisTemplate redisTemplate;

    @Override
    protected void doFilterInternal(HttpServletRequest request,
                                    HttpServletResponse response,
                                    FilterChain filterChain)
            throws ServletException, IOException {
        String customerId = request.getHeader("X-Customer-Id");
        if (customerId == null) { filterChain.doFilter(request, response); return; }
        String key = "rate_limit:orders:" + customerId;
        long now = Instant.now().toEpochMilli();
        long windowStart = now - WINDOW.toMillis();
        List<Object> results = redisTemplate.executePipelined((RedisCallback<Object>) conn -> {
            byte[] rawKey = key.getBytes();
            conn.zRemRangeByScore(rawKey, 0, windowStart);
            conn.zCard(rawKey);
            conn.zAdd(rawKey, now, String.valueOf(now).getBytes());
            conn.expire(rawKey, WINDOW.getSeconds());
            return null;
        });
        long currentCount = (Long) results.get(1);
        if (currentCount >= MAX_REQUESTS_PER_HOUR) {
            response.setStatus(429);
            response.setHeader("Retry-After", "60");
            response.getWriter().write("{\"error\": \"Rate limit exceeded\"}");
            return;
        }
        response.setHeader("X-RateLimit-Remaining",
            String.valueOf(MAX_REQUESTS_PER_HOUR - currentCount - 1));
        filterChain.doFilter(request, response);
    }
}
