@Component
public class DeadLetterQueueHandler {
    private final DeadLetterRepository dlqRepository;
    private final KafkaTemplate<String, String> kafkaTemplate;

    @KafkaListener(topics = {"payment.results.DLQ", "inventory.updates.DLQ"},
                   groupId = "order-service-dlq")
    @Transactional
    public void handleDeadLetter(ConsumerRecord<String, String> record, Acknowledgment ack) {
        DeadLetterEntry entry = new DeadLetterEntry();
        entry.setOriginalTopic(record.topic().replace(".DLQ", ""));
        entry.setPayload(record.value());
        entry.setStatus(DLQStatus.PENDING);
        record.headers().forEach(h -> {
            if ("kafka_dlt-exception-message".equals(h.key()))
                entry.setErrorMessage(new String(h.value()));
        });
        dlqRepository.save(entry);
        ack.acknowledge();
    }

    public void retryMessage(UUID entryId) {
        DeadLetterEntry entry = dlqRepository.findById(entryId).orElseThrow();
        kafkaTemplate.send(entry.getOriginalTopic(), entry.getPayload())
            .whenComplete((r, ex) -> {
                entry.setStatus(ex != null ? DLQStatus.PENDING : DLQStatus.RETRIED);
                entry.setRetryCount(entry.getRetryCount() + 1);
                dlqRepository.save(entry);
            });
    }
}
